  "pos.nocam": "கேமரா ஸ்கேன் Android-இல் Chrome அல்லது Edge-இல் வேலை செய்யும். இங்கே USB அல்லது Bluetooth பார்கோட் ஸ்கேனர் பயன்படுத்துங்கள், அல்லது கோடை டைப் செய்யுங்கள்.",
