  "sb.local": "டேட்டா ஹோம் திறக்கவில்லை, எனவே இந்தத் தளத்தில் இந்த பிரவுசரில் மட்டும் சேவ் ஆகியுள்ளது. அடுத்த முறை இது டேட்டா ஹோமுக்குச் செல்லும்.",
