  "stk.how": "வரவு = பர்ச்சேஸ் பில், செல்ஃப் இன்வாய்ஸ், வாடிக்கையாளர் திருப்பிய சரக்கு. செலவு = சேல் பில், கேஷ் மெமோ, சப்ளையருக்குத் திருப்பிய சரக்கு. மதிப்பு = க்ளோசிங் அளவு × GST இல்லாத சராசரி வாங்கிய விலை.",
