  "stk.minh": "கையிருப்பு இந்த அளவுக்கு அல்லது கீழே வந்தால் ஐட்டம் குறைந்த ஸ்டாக்கில் காட்டப்படும். அலர்ட் வேண்டாமெனில் காலியாக விடுங்கள்.",
