  "b1.rep_none": "இப்போது மீண்டும் போட வேண்டிய பில் எதுவும் இல்லை.",
  "b1.rep_made": "{n} பில்கள் போடப்பட்டன. அவை விற்பனையில் உள்ளன.",
  "b1.rep_all": "எல்லா மீண்டும் வரும் பில்கள்",
  "b1.rep_from": "{d} அன்று {no} இலிருந்து · {n} காப்பிகள் போடப்பட்டன",
  "b1.rep_how": "பில்லை மீண்டும் போட அதை இன்வாய்ஸ் மேக்கரில் திறந்து \"இந்த பில்லை மீண்டும் போடு\" இல் \"ஒவ்வொரு மாதமும்\" அல்லது \"ஒவ்வொரு காலாண்டும்\" தேர்ந்தெடுக்கவும்.",
  "b1.rep_stop": "மீண்டும் போடுவதை நிறுத்து",
