NS.addLang("ta", {
  "db.blocked": "நீங்கள் சேமித்த தரவு, புதுப்பிப்புக்கு முந்தைய வேறொரு Nivesh Sahayak டேபில் இன்னும் திறந்திருக்கிறது. மற்ற Nivesh Sahayak டேப்களை மூடுங்கள் அல்லது ரீலோட் செய்யுங்கள். பிறகு இந்தப் பக்கம் தானாகவே தொடரும்.",
  "hs.x.h": "பொருந்தக்கூடிய விலக்குகள் (அறிவிப்பு 12/2017)",
  "hs.x.lead": "உங்கள் சப்ளை இந்த என்ட்ரிகளில் ஒன்றின் விவரத்துக்குப் பொருந்தினால், அதற்கு நிபந்தனை இருந்தால் அதையும் பூர்த்தி செய்தால் மட்டுமே GST நில் (விலக்கு). இல்லையென்றால் மேலே உள்ள விகிதம் பொருந்தும்.",
  "hs.x.none": "விலக்கு என்ட்ரி எதிலும் இந்த ஹெடிங் இல்லை. எந்த சர்வீஸுக்கும் எழுதப்பட்ட என்ட்ரிகள் அப்போதும் பொருந்தலாம் (கீழே).",
  "hs.x.any": "எந்த சர்வீஸுக்கும் எழுதப்பட்ட விலக்குகள், பெரும்பாலும் அரசு அமைப்புகள், அறக்கட்டளைகள் வழங்குவது அல்லது அவற்றுக்கு வழங்குவது ({n})",
  "hs.x.nil": "விலக்கு",
  "hs.x.cond": "நிபந்தனை",
  "hs.x.defs": "இங்கே பயன்படுத்திய சொற்களின் பொருள் (அறிவிப்பின் பத்தி 2)",
  "hs.x.expl": "விளக்கம் (அறிவிப்பின் பத்தி 3)",
  "hs.x.maybe": "விகித அறிவிப்பில் விகிதம் {r}, ஆனால் இந்த ஹெடிங்கின் சில சர்வீஸ்களுக்கு விலக்கு உண்டு. GST வசூலிக்கும் முன் கீழே உள்ள விலக்குகளைப் பாருங்கள்.",
  "hs.x.ind": "அறிவிப்பின் ஹெடிங்குகள் குறிப்புக்காக மட்டுமே என்று அது சொல்கிறது (பத்தி 3), எனவே விலக்குகளை சர்ச் பாக்ஸில் சொற்களாலும் தேடுங்கள்.",
  "hs.x.src": "விலக்குகள் அறிவிப்பு 12/2017-Central Tax (Rate)-லிருந்து அப்படியே, 07/2026 வரையிலான எல்லாத் திருத்தங்களுடன் (1 நவம்பர் 2026 முதல் அமலில்). சரிபார்த்தது: {d}.",
  "hs.x.found": "விலக்கு என்ட்ரிகள்"
});
