  "grp.p_party": "வாடிக்கையாளர்களையும் சப்ளையர்களையும் குரூப்களாக பிரியுங்கள், உதாரணமாக ரீடெய்ல் வாடிக்கையாளர்கள் அல்லது லூதியானா ரூட். வாடிக்கையாளர்கள், சப்ளையர்கள் ஏற்கனவே உள்ளன; உங்கள் குரூப்கள் அவற்றின் கீழ் வரும், ஒவ்வொன்றிலும் சப்-குரூப்கள் இருக்கலாம். Tally-யில் இதே குரூப்கள் Sundry Debtors, Sundry Creditors கீழ் போகும்.",
