  "mf.tl_over": "கால வரம்பு கடந்தது",
  "mf.overmsg": "{n} வரிகள் கால வரம்பைக் கடந்துவிட்டன. இன்புட் அனுப்பிய 1 ஆண்டுக்குள்ளும் கேப்பிட்டல் குட்ஸ் 3 ஆண்டுக்குள்ளும் திரும்ப வர வேண்டும், இல்லையெனில் அனுப்பிய நாளே விற்றதாகக் கொண்டு GST கட்ட வேண்டும் (CGST சட்டம், பிரிவு 143).",
