  "mf.itc": "ITC-04 (ஜாப் வொர்க் ரிட்டர்ன்)",
  "mf.itch": "விதி 45(3), 1 அக்டோபர் 2021 முதல் அமலில் (5 நவம்பர் 2026 அன்று சரிபார்த்தது): கடந்த ஆண்டு டர்ன்ஓவர் ₹5 கோடிக்கு மேல் இருந்தால் ஆண்டுக்கு இருமுறை தாக்கல் செய்யுங்கள் (ஏப்ரல் முதல் செப்டம்பர் அக்டோபர் 25 க்குள், அக்டோபர் முதல் மார்ச் ஏப்ரல் 25 க்குள்); இல்லையெனில் ஆண்டுக்கு ஒருமுறை ஏப்ரல் 25 க்குள். தாக்கல் செய்யும் முன் GST போர்ட்டலில் ITC-04 வடிவத்தைப் பாருங்கள்.",
