/* User test fixes 2 */
NS.addLang("ta", {
  "c8.w.late": "இந்த ஸ்டேட்மெண்ட் {d} க்குள் தாக்கல் செய்ய வேண்டியது. இன்னும் தாக்கல் செய்யவில்லை என்றால் இப்போதே செய்து வரியைக் கட்டுங்கள்: தாமதமாகக் கட்டும் வரிக்கு ஆண்டுக்கு 18% வட்டி உண்டு (CGST சட்டம் பிரிவு 50). வட்டியை \"தாமதமாகச் செலுத்தினால் வட்டி\" பெட்டியில் எழுதுங்கள்.",
  "hs.f.syn": "அரசுப் பட்டியலில் உள்ள சொற்களாலும் தேடப்பட்டது: \"{w}\".",
  "hs.f.gst": "ஜிஎஸ்டி {r}",
  "hs.f.gstmany": "ஜிஎஸ்டி {r}: திறந்து தேர்வு செய்யுங்கள்",
  "sw.only": "ஸ்டாக்கில் {n} {u} மட்டுமே உள்ளது. பில் இருந்தும் சேவ் ஆகும்; ஸ்டாக் மைனஸில் காட்டும்.",
  "sw.none": "இந்த ஐட்டம் ஸ்டாக்கில் இல்லை. பில் இருந்தும் சேவ் ஆகும்; ஸ்டாக் மைனஸில் காட்டும்.",
  "rb.h": "{p} இன் நிலுவை பில்கள்",
  "rb.due": "{a} நிலுவை",
  "rb.none": "நீங்கள் சேவ் செய்த டேட்டாவில் {p} இன் நிலுவை பில் எதுவும் இல்லை.",
  "rb.hint": "இந்தப் பணம் எந்த பில்களுக்கானது என்று அவற்றில் டிக் செய்யுங்கள். பணம் முதலில் டிக் செய்த பில்லிலிருந்து பிரிக்கப்படும், ஆப்பில் அந்த பில்கள் பணம் செலுத்தியது அல்லது பகுதி செலுத்தியது எனக் காட்டும்.",
  "gc.frombiz": "உங்கள் பிசினஸ் {b} இலிருந்து நிரப்பப்பட்டது. நீங்கள் GSTR-1, GSTR-3B ஐ ஒவ்வொரு காலாண்டும் (QRMP) தாக்கல் செய்தால் மேலே அதைத் தேர்வு செய்யுங்கள்.",
  "uf.waupi": "\n{a} ஐ UPI மூலம் இதற்கு அனுப்புங்கள்: {u}",
  "g1.w.r28": "{no}: ஒரு வரியில் ஜிஎஸ்டி 28% உள்ளது, ஆனால் 1 பிப்ரவரி 2026 முதல் 28% ஜிஎஸ்டி ரேட் இல்லை. இந்த பில்லின் ரேட்டைச் சரிபாருங்கள்.",
  "uf.add2b": "என் வாங்குதல்களில் சேர்",
  "uf.add2bq": "{p} இன் பில் {no} ஐ GSTR-2B தொகைகளுடன் பர்சேஸ் பில்லாக (இன்னும் பணம் செலுத்தவில்லை) சேவ் செய்யவா? ஐட்டம்களையும் HSN கோடுகளையும் பின்னர் ஆப்பில் சேர்க்கலாம்.",
  "uf.add2bok": "பர்சேஸ் பில் {no} சேவ் ஆனது. இப்போது இது உங்கள் கணக்கில் உள்ளது, இங்கே பொருந்தியது.",
  "uf.tdsr": "அல்லது TDS ரேட் (%)",
  "uf.tdsa": "அல்லது TDS தொகை (₹)",
  "uf.pfapp": "இங்கே செலவு எப்படிக் கணக்கிடப்படுகிறது: விற்ற ஒவ்வொரு ஐட்டத்தின் செலவும் அதன் சராசரி வாங்கிய விலையில், ஒருபோதும் வாங்கப்படாவிட்டால் ஐட்டத்துடன் சேவ் செய்த வாங்கும் விலையில். ப்ராஃபிட் அண்ட் லாஸ் பக்கம் வேறு வழியில் கணக்கிடுகிறது (வாங்கியதிலிருந்து குளோசிங் ஸ்டாக்கைக் கழித்து), எனவே எல்லா பர்சேஸ் பில்களும் சேர்க்கப்படும் வரை இரண்டிலும் வேறுபாடு இருக்கலாம்.",
  "uf.pfpl": "இங்கே செலவு எப்படிக் கணக்கிடப்படுகிறது: வாங்கியது + ஓப்பனிங் ஸ்டாக் − குளோசிங் ஸ்டாக். ஆப்பின் ப்ராஃபிட் ரிப்போர்ட் ஒவ்வொரு விற்பனையின் செலவையும் ஐட்டத்தின் சராசரி வாங்கிய விலையில் (அல்லது ஒருபோதும் வாங்காத ஐட்டத்தின் சேவ் செய்த வாங்கும் விலையில்) கணக்கிடுகிறது, எனவே எல்லா பர்சேஸ் பில்களும் சேர்க்கப்படும் வரை இரண்டிலும் வேறுபாடு இருக்கலாம்."
});

