  "tf.fmth": "கடைகள், உரிமையாளர்கள், ஃபர்ம்கள் பொதுவாக T ஃபார்மேட் வைக்கின்றனர், Tally மற்றும் பெரும்பாலான கணக்காளர்கள், வங்கிகள் போல. கம்பெனிகளுக்கு ஷெட்யூல் III கட்டாயம். ஆப்பும் லாப நஷ்டப் பக்கமும் இந்தத் தேர்வையே பின்பற்றும்.",
