  "tf.dxh": "டைரக்ட் செலவுகள் (சரக்கு வாடகை, ஏற்றிச் செல்லும் கூலி, கூலி, தொழிற்சாலை மின்சாரம் மற்றும் எரிபொருள், பேக்கிங்) டிரேடிங் கணக்குக்குச் சென்று கிராஸ் லாபத்தைக் குறைக்கும். இன்டைரக்ட் செலவுகள் (வாடகை, அலுவலகச் சம்பளம், ஃபோன், விளம்பரம், வங்கிக் கட்டணம்...) லாப நஷ்ட கணக்குக்குச் செல்லும்.",
