  "fx.dep_q": "FY {fy}-க்கு {d} வரை {a} தேய்மானத்தை, {d} தேதியில் பதிவுசெய்யவா?",
  "fx.pybs": "முந்தைய ஆண்டு: {b} அன்று, கடந்த ஆண்டு இறுதி.",
  "fx.pybsnone": "முந்தைய ஆண்டு ({b} அன்று): பதிவுகள் இல்லை, — காட்டப்பட்டது.",
  "fx.hs_drop": "அதிகாரப் பட்டியலில் இல்லை, தேடலில் விடப்பட்டது: {w}",
  "fx.fm_dwages": "கூட்டு: நேரடிக் கூலி",
  "fx.fm_ovh": "கூட்டு: தொழிற்சாலை மேல்செலவுகள்",
  "fx.cmc": "பயன்படுத்திய பொருட்களின் செலவு",
  "fx.chgfg": "தயார் பொருட்கள், முடியாத வேலை, வணிக இருப்பு ஆகியவற்றில் மாற்றம்",
  "fx.osfg": "தொடக்க இருப்பு (தயார் பொருட்கள், முடியாத வேலை, வணிக இருப்பு)",
  "fx.csfg": "கழி: இறுதி இருப்பு (தயார் பொருட்கள், முடியாத வேலை, வணிக இருப்பு)",
  "fm.h_capi": "கொண்டுவந்த மூலதனம்",
  "fm.h_recvc": "வாடிக்கையாளர்களிடமிருந்து பெற்றது",
  "b2.ac_ocl": "நிலுவைச் செலவு அல்லது ஒதுக்கீடு",
  "b2.ac_oca": "முன்கூட்டிச் செலுத்திய செலவு அல்லது வர வேண்டிய வருமானம்",
  "fx.l_opening": "தொடக்க இருப்புகள் (மூலதனத்தில் வேறுபாடு)",
  "fx.cl_notp": "{n} இந்த வணிகத்தில் சேமித்த பங்குதாரர் ({p}) அல்ல. இருந்தாலும் சேமிக்கவா?",
  "fx.fm_loss": "இந்தக் காலத்தில் லாபம் இல்லை, எனவே பங்குதாரர்களுக்கு வட்டியோ சம்பளமோ இல்லை ({x} உரியதாக இருந்திருக்கும்). ஒப்பந்தம் நஷ்டத்திலும் அனுமதித்தால் வணிக விவரங்களில் மாற்றுங்கள்.",
  "pb.setfor": "இதன் அமைப்புகள்",
  "pb.setforh": "ஒவ்வொரு வணிகத்துக்கும் தனி எண் வரிசை, புதிய ஆவண இயல்புகள், பூட்டு தேதி, இறுதிக் கணக்கு தேர்வுகள் இருக்கும். இயல்பு வணிகமும் காப்பு நினைவூட்டலும் அனைவருக்கும் ஒன்றே.",
  "pb.usedby": "யாருக்கு",
  "pb.usedbyh": "எல்லா வணிகங்களுக்கும் விடுங்கள், அல்லது ஒரே வணிகத்துக்கு வைத்தால் அங்கே மட்டும் காட்டும்.",
  "pb.allbiz": "எல்லா வணிகங்களும்",
  "pb.only": "{b} மட்டும்",
  "fx.as2": "இங்கே செய்த தயார் பொருட்கள் முழுச் செலவில் (AS 2) மதிப்பிடப்படுகின்றன: தொழிற்சாலைச் செலவு {oh} {m} உற்பத்தியில் பகிரப்பட்டது ({p}%), எனவே இருப்புப் பொருட்களில் {u} சேர்க்கப்பட்டது.",
