  "hd.seth": "எல்லா வகை வருமானம் மற்றும் செலவுக்கும் தயாரான ஹெட்கள், Tally குரூப்புடன். செலவுப் படிவம், ஜர்னல் என்ட்ரி மற்றும் இதர வருமானத்தில் இவையே காட்டப்படும்.",
  "hd.own": "உங்கள் சொந்த ஹெட்கள்",
  "hd.ownh": "பட்டியலில் இல்லாத ஹெட்டைச் சேர்த்து அது எந்த வகை என்று சொல்லுங்கள். செலவுப் படிவத்தில் எழுதிய புதிய பெயர் தானாக இங்கே சேரும்.",
