  "hd.info": "{t} · Tally குரூப்: {g}.",
  "hd.blockw": "இதன் GST-ஐ க்ளெய்ம் செய்ய முடியாது (CGST சட்டம் பிரிவு 17(5)). இன்புட் டாக்ஸ் கிரெடிட் டிக்கை எடுக்கவும்.",
  "hd.rcmw": "பெரும்பாலும் ரிவர்ஸ் சார்ஜ்: சப்ளையர் போக்குவரத்து நிறுவனம் (GTA) அல்லது வக்கீல் என்றால் செல்ஃப் இன்வாய்ஸ் போட்டு GST-ஐ நீங்களே கட்டவும்.",
  "hd.tdsw": "TDS பொருந்தலாம்: பிரிவு {s}.",
  "hd.faw": "பல ஆண்டுகள் பயன்படும் பொருள் வாங்கினீர்களா? அதை ஃபிக்ஸ்டு அசெட்டில் சேர்க்கவும்.",
