  "w5.acct": "என் அக்கவுண்டில் சேர்",
  "w5.h_salary": "சம்பளம், PF, ESI, தொழில் வரி மற்றும் TDS இந்த பிசினஸின் புக்ஸில் போகும். வேறு ஒருவருக்காகச் செய்த ஸ்லிப் என்றால் டிக்கை எடுங்கள்.",
  "w5.h_rent": "நீங்கள் வீட்டு உரிமையாளர், வாடகை இந்த பிசினஸுக்கு வந்தது என்றால் டிக் வையுங்கள்: புக்ஸில் வாடகை வருமானம் ஆகும். குடியிருப்பவர் கையெழுத்துக்காகச் செய்த ரசீது என்றால் டிக்கை எடுங்கள்.",
  "w5.h_petty": "கொடுத்த ஒவ்வொரு செலவும் அதன் ஹெட் மற்றும் தேதியில் இந்த பிசினஸின் புக்ஸில் போகும். பெட்டி கேஷில் போட்ட பணம் மீண்டும் கணக்கில் வராது.",
