  "w5.h_erpf": "சம்பளத்துக்கு மேல் உங்கள் சொந்தப் பங்கு: பேசிக்கில் 12%, ₹25,000 வரை. \"PF, ESI, புரொஃபஷனல் டாக்ஸ், TDS கணக்கிடவும்\" இதை நிரப்பும்.",
  "w5.eresi": "முதலாளியின் ESI (₹)",
  "w5.paydate": "சம்பளம் கொடுத்த தேதி",
  "w5.h_paydate": "சம்பளம் கொடுக்கும் வரை காலியாக விடுங்கள். அதுவரை புக்ஸில் சம்பளம் பாக்கி என்று காட்டும்.",
