  "pu.v.noz": "குறைந்தது ஒரு நாசிலின் தொடக்க மற்றும் இறுதி ரீடிங்கை டைப் செய்யுங்கள்.",
  "pu.v.price": "இந்த நாசிலின் ஒரு லிட்டர் விலையை டைப் செய்யுங்கள்.",
  "pu.v.fuel": "இந்த நாசிலின் எரிபொருளை டைப் செய்யுங்கள்.",
  "pu.v.cust": "கடன் வாடிக்கையாளரின் பெயரை டைப் செய்யுங்கள்.",
  "pu.v.exp": "கல்லாவிலிருந்து கொடுத்த தொகை கேஷ் விற்பனையை விட அதிகம்.",
  "nav.marketplace": "மார்க்கெட்பிளேஸ் பேஅவுட் சரிபார்ப்பு",
  "f.marketplace": "மார்க்கெட்பிளேஸ் பேஅவுட் ரீகன்சிலியேஷன்",
