  "mk.title": "மார்க்கெட்பிளேஸ் பேஅவுட் சரிபார்ப்பு",
  "mk.open": "பேஅவுட் ஃபைலைத் திற",
  "mk.other": "வேறு ஃபைலைத் திற",
  "mk.sample": "ஒரு மாதிரி ஃபைலை டவுன்லோட் செய்",
  "mk.samplec": "ஒரு ஆர்டருக்கு ஒரு வரி உள்ள மாதிரியா? OK = ஆம், Cancel = ஒரு சார்ஜுக்கு ஒரு வரி உள்ள மாதிரி.",
  "mk.start": "மார்க்கெட்பிளேஸ் உங்களுக்கு என்ன கொடுத்தது என்று சரிபாருங்கள்",
  "mk.starth": "செல்லர் போர்ட்டலிலிருந்து டவுன்லோட் செய்த பேஅவுட் (செட்டில்மென்ட்) ஃபைலை Excel அல்லது CSV ஆகத் திறங்கள். இது இந்த பிரவுசரில் மட்டும் படிக்கப்படும்.",
  "mk.s1": "ஃபைலைத் திறங்கள். டூல் தலைப்புகளை வைத்து காலம்களைக் கண்டுபிடிக்கும்; தவறான காலத்தை மாற்றுங்கள்.",
  "mk.s2": "ஒவ்வொரு ஆர்டரும் உங்கள் சேவ் செய்த இன்வாய்ஸ்களுடன் ஆர்டர் id மூலம், பிறகு தொகை மற்றும் தேதி மூலம் பொருத்தப்படும்.",
  "mk.s3": "ரிட்டர்ன்கள், கட்டணங்கள், TCS மற்றும் TDS, நீங்கள் பில் போடாத ஆர்டர்கள், பேஅவுட் சரியாகக் கூடுகிறதா என்று பாருங்கள்.",
  "mk.layout": "ஒவ்வொரு மார்க்கெட்பிளேஸின் ஃபைல் அமைப்பும் இந்த டூலுக்குத் தெரியாது, அது அவ்வப்போது மாறும். உங்கள் ஃபைல் சரியாகப் படிக்கப்படவில்லை என்றால், “எந்த காலம் எது” என்பதில் காலம்களை நீங்களே தேர்ந்தெடுங்கள், அல்லது இது படிக்கும் இரண்டு வடிவங்களைப் பார்க்க மாதிரி ஃபைலை டவுன்லோட் செய்யுங்கள்.",
  "mk.readfail": "இந்த ஃபைலைப் படிக்க முடியவில்லை. Excel (.xlsx) அல்லது CSV ஃபைலைப் பயன்படுத்துங்கள்.",
  "mk.read": "{n} ஆர்டர்கள் படிக்கப்பட்டன.",
  "mk.from": "ஃபைல்: {f}. இப்படிப் படிக்கப்பட்டது: {m}.",
  "mk.mode.wide": "தனித்தனி காலம்களுடன் ஒரு ஆர்டருக்கு ஒரு வரி",
  "mk.mode.long": "ஒரு சார்ஜுக்கு ஒரு வரி, சார்ஜ் வகை மற்றும் ஒரு தொகையுடன்",
  "mk.cols": "எந்த காலம் எது",
  "mk.colsh": "ஒவ்வொரு ஐட்டத்துக்கும் ஃபைலின் காலத்தைத் தேர்ந்தெடுங்கள். ஃபைலில் இல்லாத ஐட்டம் காலியாக இருக்கலாம். ஒரு சார்ஜுக்கு ஒரு வரி உள்ள ஃபைலுக்கு, “சார்ஜ் வகை”, “தொகை” இரண்டையும் தேர்ந்தெடுங்கள்.",
