  "mk.prob.order": "ஆர்டர் id காலம் கிடைக்கவில்லை. “எந்த காலம் எது” என்பதில் தேர்ந்தெடுங்கள்.",
  "mk.prob.amounts": "குறைந்தது ஒரு தொகை காலத்தைத் தேர்ந்தெடுங்கள்: விற்பனை மதிப்பு, நிகர பேஅவுட், அல்லது சார்ஜ் வகையுடன் தொகை.",
  "mk.settings": "உங்கள் விவரங்கள் மற்றும் சரிபார்க்க வேண்டிய ரேட்டுகள்",
  "mk.mname": "மார்க்கெட்பிளேஸ் பெயர்",
  "mk.mnameh": "உங்கள் இன்வாய்ஸ்களில் எழுதுவது போல. அங்கே செய்த, ஃபைலில் இல்லாத விற்பனைகளைக் கண்டுபிடிக்கப் பயன்படும்.",
  "mk.days": "தொகை மூலம் பொருத்த நாட்கள்",
  "mk.tcsrate": "சரிபார்க்க வேண்டிய TCS ரேட் (%)",
  "mk.tcsrateh": "ரேட்டை டைப் செய்யுங்கள். காலி = சரிபார்ப்பு இல்லை. Section 52 CGST; 10 ஜூலை 2024 முதல் ரேட் 0.5% (14 நவம்பர் 2026 அன்று சரிபார்க்கப்பட்டது): உறுதி செய்யுங்கள்.",
  "mk.tdsrate": "சரிபார்க்க வேண்டிய TDS ரேட் (%)",
  "mk.tdsrateh": "ரேட்டை டைப் செய்யுங்கள். காலி = சரிபார்ப்பு இல்லை. Section 393 (old 194-O); 1 அக்டோபர் 2024 முதல் 0.1% (14 நவம்பர் 2026 அன்று சரிபார்க்கப்பட்டது): உறுதி செய்யுங்கள்.",
  "mk.gst": "விற்பனை மதிப்புகளில் இந்த ரேட்டில் GST சேர்ந்துள்ளது (%)",
  "mk.gsth": "உங்கள் ஃபைலில் வரிக்குட்பட்ட மதிப்பு காலம் இல்லாவிட்டால் மட்டும்: TCS, GST இல்லாத மதிப்பில் சரிபார்க்கப்படும்.",
