  "mk.f.miss": "ஃபைலில் உள்ள {n} ஆர்டர்(களுக்கு) பொருந்தும் உங்கள் இன்வாய்ஸ் இல்லை.",
  "mk.f.nofile": "உங்கள் இன்வாய்ஸ்களில் {n} இந்த மார்க்கெட்பிளேஸைக் குறிப்பிடுகின்றன, ஆனால் ஃபைலில் இல்லை.",
  "mk.f.nocn": "{n} ரிட்டர்ன்(களுக்கு) உங்கள் கிரெடிட் நோட் இல்லை.",
  "mk.f.diff": "{n} ஆர்டர்(கள்) அவற்றின் பகுதிகளின் கூட்டுத்தொகையை விட {v} வித்தியாசமாகக் கொடுக்கப்பட்டன.",
  "mk.f.short": "ஃபைலில் கொடுத்ததாகச் சொல்வதை விட {v} குறைவாக உங்களுக்கு வந்தது.",
  "mk.f.more": "ஃபைலில் கொடுத்ததாகச் சொல்வதை விட {v} அதிகமாக உங்களுக்கு வந்தது.",
  "mk.f.ok": "உங்களுக்கு வந்தது ஃபைலுடன் பொருந்துகிறது.",
  "mk.recvh": "உங்கள் பேங்கிற்கு வந்தது",
