  "mk.receivedh": "குறைவு ஏதும் உள்ளதா என்று பார்க்க உங்கள் பேங்க் ஸ்டேட்மென்ட்டிலிருந்து டைப் செய்யுங்கள்.",
  "mk.paydate": "வந்த தேதி",
