  "mk.deducted": "ஃபைலில் கழிக்கப்பட்டது",
  "mk.expected": "நீங்கள் டைப் செய்த ரேட்டில்",
  "mk.diff": "வித்தியாசம்",
  "mk.tcsl": "TCS (section 52 CGST)",
  "mk.tdsl": "TDS (section 393 (old 194-O))",
  "mk.taxnote": "TCS, விற்பனையிலிருந்து ரிட்டர்ன்களைக் கழித்த GST இல்லாத மதிப்பில் சரிபார்க்கப்படுகிறது. TDS, மொத்த விற்பனையிலிருந்து ரிட்டர்ன்களைக் கழித்த தொகையில் சரிபார்க்கப்படுகிறது. சிறு விற்பனையாளர்களின் ஆர்டர்களுக்கு TDS விலக்கு இருக்கலாம், ஒரு விற்பனையாளருக்கு குறைந்த ரேட் சான்றிதழ் இருக்கலாம். க்ளெய்ம் செய்யும் முன் GST போர்ட்டலில் TCS கிரெடிட்டையும் (TCS credit received), Form 26AS அல்லது AIS-இல் TDS-ஐயும் சரிபாருங்கள்.",
  "mk.refs": "ஃபைலில் உள்ள செட்டில்மென்ட்கள்",
  "mk.refsh": "ஒவ்வொரு செட்டில்மென்ட்டின் மொத்தத்தையும் உங்கள் பேங்க் ஸ்டேட்மென்ட்டில் உள்ள கிரெடிட்டுடன் பொருத்துங்கள் (பேங்க் ரீகன்சிலியேஷன் டூல் இதைச் செய்யும்).",
