  "rq.gsth": "உங்கள் அக்கவுண்டன்ட்டிடம் சரிபாருங்கள். வாடகைதாரர் பதிவு செய்த பிசினஸ் இல்லையென்றால், குடியிருப்பு வீட்டு வாடகைக்கு வழக்கமாக GST இல்லை; வீட்டு உரிமையாளர் பதிவு செய்திருந்தால் கடைகள் மற்றும் ஆபீஸ்களின் வாடகைக்கு 18% வரி; பதிவு செய்யாத வீட்டு உரிமையாளர் அல்லது பதிவு செய்த வாடகைதாரருக்குக் குடியிருப்பு வாடகை போன்ற சில நிலைகளில் ரிவர்ஸ் சார்ஜ் பொருந்தும்.",
