  "pr.month": "மாதம்",
  "pr.emp": "ஊழியர்",
  "pr.saved": "சேவ் ஆனது {f}",
  "pr.intro": "ஒவ்வொரு நாளும் யார் வேலைக்கு வந்தார்கள் என்று குறியுங்கள். சம்பள நாட்கள் சம்பளச் சீட்டுக்குச் செல்லும் (சம்பளச் சீட்டு › ஊழியரைத் தேர்ந்தெடுங்கள்: நாட்கள் தானாக நிரம்பும்), PF மற்றும் ESI ஃபைல்களுக்கும் செல்லும். எதுவும் இந்த டிவைஸை விட்டு வெளியே போகாது.",
  "pr.noemp": "இந்த மாதம் இன்னும் எந்த ஊழியரும் வேலை செய்யவில்லை. முதலில் உங்கள் ஊழியர்களைச் சேருங்கள் (பெயர், சேர்ந்த தேதி, UAN மற்றும் ESI எண்கள்).",
