  "pr.tap": "மாற்ற ஒரு நாளைத் தட்டுங்கள்: வந்தார், வரவில்லை, அரை நாள், சம்பள லீவு, சம்பளமில்லா லீவு, விடுமுறை, வார விடுமுறை, பிறகு மீண்டும் காலி. காலியாக விட்ட நாட்கள் நீங்கள் குறிக்கும் வரை சம்பள நாட்களாகக் கணக்கிடப்படாது.",
