  "pr.howsheet": "எப்படி நிரப்புவது",
  "pr.howhead": "ஒவ்வொரு நாளின் கீழும் P, A, H, PL, UL, HOL அல்லது WO போடுங்கள். தலைப்பு வரியையும் ஊழியர் பெயர்களையும் அப்படியே வையுங்கள்.",
  "pr.noxl": "Excel ஃபைலை உருவாக்க முடியவில்லை. CSV ஃபைலைப் பயன்படுத்துங்கள்.",
  "pr.imp_head": "ஃபைலில் Employee மற்றும் நாள் எண்கள் 1, 2, 3 … உள்ள தலைப்பு வரி இல்லை. முதலில் ஷீட்டை எக்ஸ்போர்ட் செய்து அதை நிரப்புங்கள்.",
  "pr.imp_days": "நாள் காலம்கள் (1, 2, 3 …) எதுவும் கிடைக்கவில்லை.",
  "pr.imp_xls": "இது பழைய .xls ஃபைல். .xlsx அல்லது CSV ஆக சேவ் செய்து மீண்டும் முயற்சி செய்யுங்கள்.",
  "pr.imp_fail": "ஃபைலைப் படிக்க முடியவில்லை.",
  "pr.impdone": "{n} ஊழியர்(களின்) வருகைப் பதிவு இம்போர்ட் ஆனது.",
  "pr.impunk": "உங்கள் ஊழியர் லிஸ்ட்டில் இல்லாத {n} பெயர்(கள்): {l}.",
  "pr.impbad": "புரியாத {n} செல்(கள்): {l}.",
  "pr.rates": "ரேட்டுகளும் வரம்புகளும் (விதிகள் மாறினால் மாற்றுங்கள்)",
  "pr.reset": "வழக்கமான மதிப்புகளுக்குத் திரும்பு",
  "pr.rates_pf": "வழக்கமான EPF விதிகளிலிருந்து அமைக்கப்பட்டது: சம்பள வரம்பு மாதம் ₹25,000 (17 செப்டம்பர் 2026 முதல்), ஊழியர் 12%, பென்ஷன் (EPS) 8.33%, EDLI 0.5%, நிர்வாகக் கட்டணம் 0.5% குறைந்தபட்சம் ₹500. கட்டும் முன் EPFO தளத்தில் சரிபாருங்கள்.",
  "pr.rates_esi": "சம்பளத்தில் ஊழியர் 0.75%, முதலாளி 3.25%, ஒவ்வொன்றும் அடுத்த ரூபாய்க்கு மேல்நோக்கி ரவுண்ட் செய்யப்படும் (Social Security (Central) Rules, 2026, rule 19). சம்பள வரம்பு மாதம் ₹21,000: தற்போதைய வரம்பை ESIC தளத்தில் சரிபாருங்கள். தினசரி சம்பளம் ₹176 அல்லது அதற்குக் குறைவாக இருந்தால் ஊழியர் பங்கு இல்லை (ESIC contribution பக்கம்).",
  "pr.f_ceil": "EPF சம்பள வரம்பு (₹)",
  "pr.f_epf": "EPF ரேட் %",
  "pr.f_eps": "பென்ஷன் (EPS) ரேட் %",
  "pr.f_edli": "EDLI ரேட் %",
  "pr.f_admin": "நிர்வாகக் கட்டணம் %",
  "pr.f_adminmin": "நிர்வாகக் கட்டணம் குறைந்தபட்சம் (₹)",
  "pr.f_eceil": "ESI சம்பள வரம்பு (மாதம் ₹)",
  "pr.f_ee": "ஊழியர் பங்கு %",
  "pr.f_er": "முதலாளி பங்கு %",
  "pr.f_daily": "இந்த தினசரி சம்பளம் வரை ஊழியர் பங்கு இல்லை (₹)",
  "pr.pfintro": "மாதத்தின் சம்பளச் சீட்டுகளிலிருந்து EPFO unified portal-க்கான ECR டெக்ஸ்ட் ஃபைலும் சலான் தொகைகளும் உருவாகின்றன. முதலில் சீட்டுகளைப் போடுங்கள் (சம்பளம் டேப்); சீட்டு இல்லாத ஊழியர்கள் கீழே காட்டப்படுவார்கள்.",
  "pr.unver_pf": "அப்லோட் செய்யும் முன் சரிபாருங்கள்: இது உருவாக்கப்பட்டபோது (14 நவம்பர் 2026) EPFO-வின் சொந்த ஃபைல் அமைப்பு ஆவணத்தைத் திறக்க முடியவில்லை. 11 ஃபீல்டுகளும் அவற்றின் வரிசையும் பேரோல் சாஃப்ட்வேர் நிறுவனங்கள் வெளியிட்டதைப் பின்பற்றுகின்றன. ஃபைலை EPFO போர்ட்டலின் ECR பக்கத்தில் அப்லோட் செய்யுங்கள்; போர்ட்டல் ஒரு வரியை நிராகரித்தால் காரணத்தைச் சொல்லும்.",
  "pr.noslip": "இந்த மாதம் {n} ஊழியர்(களுக்கு) சம்பளச் சீட்டு இல்லை: {l}.",
  "pr.noslips": "இந்த மாதத்துக்கு சம்பளச் சீட்டு எதுவும் கிடைக்கவில்லை, அதனால் இன்னும் ஃபைல் செய்ய எதுவும் இல்லை.",
