  "pr.chnote": "{m} உறுப்பினர்(களுக்கு). அடுத்த மாதம் {d}-ஆம் தேதிக்குள் கட்ட வேண்டும்; தாமதமான பேமென்ட்டுக்கு வட்டியும் அபராதமும் சேரும். போர்ட்டல் அப்லோட் செய்த ஃபைலிலிருந்து சலான் உருவாக்கி இறுதித் தொகைகளைக் காட்டும்: இந்தக் கணக்கீட்டுடன் ஒப்பிடுங்கள்.",
  "pr.esiintro": "மாதத்தின் சம்பளச் சீட்டுகளிலிருந்து ESIC employer portal-க்கான மாதப் பங்களிப்புத் தாளும் சலான் தொகைகளும் உருவாகின்றன. சம்பளம் வரம்புக்குள் உள்ள (அல்லது அதே அரையாண்டில் முன்பே கவர் ஆன) ஊழியர்கள் மட்டும் ஃபைலில் இருப்பார்கள்.",
