  "svc.k.tax": "டாக்ஸ் இன்வாய்ஸ்",
  "svc.kindh": "GST ரேட் உங்கள் பிசினஸ் வகைக்கான பரிந்துரை; தற்போதைய ரேட்டைச் சரிபார்த்து அதன் மேல் டைப் செய்யுங்கள். சலூன், ஜிம், யோகா சர்வீஸ்கள் 22 செப்டம்பர் 2025 முதல் இன்புட் டாக்ஸ் கிரெடிட் இல்லாமல் 5% எனத் தெரிவிக்கப்பட்டது; தனியார் கோச்சிங் 18%.",
  "svc.lines": "சர்வீஸ்களும் ஐட்டம்களும்",
