  "svc.plan": "மெம்பர்ஷிப் அல்லது பேக்கேஜ்",
  "svc.planh": "தொடக்க மற்றும் முடிவுத் தேதியுடன் மெம்பர்ஷிப் அல்லது பேக்கேஜ் விற்கும்போது இதை நிரப்புங்கள். செஷன்கள் விருப்பம்.",
  "svc.planname": "பிளான் பெயர்",
