  "svc.t.mem": "கிளையன்ட்கள்",
  "svc.termsph": "காட்டிய தேதிகளுக்கு மட்டும் செல்லும். மாற்ற முடியாது. பயன்படுத்தாத செஷன்கள் காலாவதியாகும்.",
  "svc.to": "செல்லுபடி வரை",
  "svc.toh": "தொடக்கம், யூனிட், எண்ணிக்கையிலிருந்து கணக்கிடப்பட்டது; நீங்கள் மாற்றலாம்.",
