  "cv.rate": "விலை",
  "cv.taxable": "வரிக்குட்பட்ட மதிப்பு",
  "cv.round": "ரவுண்ட் ஆஃப்",
  "cv.total": "மொத்தம்",
  "cv.against": "எந்த பில்களுக்கு:",
  "cv.entries": "கணக்கில் உள்ள என்ட்ரிகள்",
  "cv.account": "அக்கவுண்ட்",
  "cv.entry": "என்ட்ரி",
  "cv.dayh": "தேதி வரிசையில் ஒவ்வொரு என்ட்ரியும் அது தொடும் அக்கவுண்ட்களுடன். ஒரு என்ட்ரி பற்றிக் கேட்க பேச்சுக் குமிழியைப் பயன்படுத்துங்கள்.",
  "cv.gsth": "கணக்குகளின் அதே என்ட்ரிகளிலிருந்து மாதம் வாரியாக: வரிக்குட்பட்ட விற்பனை (கிரெடிட் நோட்கள் கழித்து), அவுட்புட் டாக்ஸ், வாங்குதல் மற்றும் செலவுகளின் இன்புட் டாக்ஸ் கிரெடிட், நிகரத் தொகை.",
  "cv.gstnote": "ரிட்டர்ன்களுடன் சரிபார்க்க ஒரு கணக்கீடு, ரிட்டர்ன்கள் அல்ல. ரிவர்ஸ் சார்ஜ், அட்வான்ஸ்கள், செட்-ஆஃப் கணக்கில் உள்ளன, ஆனால் இங்கே தனியாகப் பிரிக்கப்படவில்லை.",
