  "sv.ct.how": "உங்கள் ஆர்டர் கடைக்கான மெசேஜாக WhatsApp-இல் திறக்கும். அங்கே Send அழுத்தும் வரை எதுவும் அனுப்பப்படாது. கடை இறுதி விலையையும் டெலிவரியையும் உறுதி செய்யும்.",
