  "sh.st.none": "எந்த வாடிக்கையாளருக்கும் நிலுவை இல்லை. முதலில் ஒரு பில் போடுங்கள்.",
  "sh.ct.t": "WhatsApp மூலம் ஆர்டர் செய்ய கேட்டலாக்",
  "sh.ct.h": "உங்கள் ஐட்டம்களும் விலைகளும் ஒரு பக்கமாகும், அங்கே வாடிக்கையாளர் அளவுகளைத் தட்டுவார். ஆர்டர் சுத்தமான டெக்ஸ்ட்டாக உங்கள் WhatsApp-க்கு வரும், அடுத்த டேபில் அதை டிராஃப்ட் சேல்ஸ் ஆர்டராக மாற்றலாம்.",
