  "sh.ct.note": "மேலே குறிப்பு",
  "sh.ct.noteph": "ஊருக்குள் மட்டும் டெலிவரி...",
  "sh.ct.mrp": "விலையை விட MRP அதிகமாக இருந்தால் காட்டு",
  "sh.ct.lim": "ஒவ்வொரு ஐட்டமும் சுமார் 20 முதல் 30 எழுத்துகளைச் சேர்க்கும். சுமார் 30 ஐட்டம்கள் வரை சாட் லிங்கில் பொருந்தும்; நீண்ட லிஸ்ட்டுக்கு ஃபைல் தேவை, இல்லையென்றால் QR ஸ்கேன் ஆகாது.",
  "sh.ct.gm": "இந்த விலைகள் மீது GST",
  "sh.ct.gm.incl": "விலைகளில் GST சேர்ந்துள்ளது",
