  "sh.rc.note": "இது வாடிக்கையாளரின் ரெக்கார்டுக்கான நகல். நீங்கள் கொடுத்த டாக்ஸ் இன்வாய்ஸே சட்டப்படியான பில்.",
  "sh.rc.none": "இந்த பிசினஸுக்கு இன்னும் இன்வாய்ஸ் அல்லது கேஷ் மெமோ சேவ் ஆகவில்லை.",
  "sh.fb.t": "கருத்து மற்றும் ரிவ்யூ QR",
  "sh.fb.h": "ஒரு சிறிய ரேட்டிங் பக்கத்தைத் திறக்கும் QR. கவுண்ட்டரில் பிரிண்ட் செய்து வையுங்கள் அல்லது பில்லில் ஒட்டுங்கள்.",
  "sh.fb.ask": "கேள்வி",
  "sh.fb.askph": "உங்கள் வருகை எப்படி இருந்தது?",
  "sh.fb.rev": "Google ரிவ்யூ லிங்க் (விருப்பம்)",
  "sh.fb.revh": "உங்கள் Google Business Profile-இல் கண்டுபிடியுங்கள்: Ask for reviews.",
  "sh.fb.wa": "கருத்துக்கான WhatsApp எண்",
  "sh.fb.badurl": "அந்த ரிவ்யூ லிங்க் அடையாளம் காணப்படவில்லை. Google கொடுக்கும் லிங்கைப் பயன்படுத்துங்கள் (g.page, search.google.com அல்லது maps).",
  "sh.fb.policy": "Google பட்டன் ஒவ்வொரு வாடிக்கையாளருக்கும் காட்டப்படும். குறைந்த ரேட்டிங்குகளுக்கு அதை மறைக்க வேண்டாம்: மகிழ்ச்சியான வாடிக்கையாளர்களிடம் மட்டும் ரிவ்யூ கேட்பதை Google அனுமதிக்காது.",
  "sh.fb.make": "கருத்து லிங்கை உருவாக்கு",
  "sh.fb.stickers": "QR ஸ்டிக்கர்களை பிரிண்ட் செய் (ஒரு பக்கத்தில் 12)",
  "sh.stk.ask": "உங்கள் வருகை எப்படி இருந்தது?",
  "sh.stk.title": "கருத்து QR ஸ்டிக்கர்கள்",
  "sh.stk.h": "சாதாரணப் பக்கத்தில் பிரிண்ட் செய்து வெட்டுங்கள், அல்லது ஸ்டிக்கர் ஷீட்டில் பிரிண்ட் செய்யுங்கள்.",
  "sh.ly.t": "லாயல்டி ஸ்டாம்ப்கள்",
  "sh.ly.h": "உதாரணமாக \"10-வது காபி இலவசம்\". ஸ்டாம்ப்கள் உங்கள் சொந்த டேட்டாவில் வைக்கப்படும். வாடிக்கையாளரின் கார்டு ஒவ்வொரு ஸ்டாம்ப்புக்குப் பிறகும் நீங்கள் மீண்டும் அனுப்பும் ஸ்னாப்ஷாட்.",
