  "sh.ly.add": "ஒரு கார்டு சேர்",
  "sh.ly.stamps": "ஸ்டாம்ப்கள்",
  "sh.ly.rw": "ரிவார்டு!",
  "sh.ly.give": "ரிவார்டு கொடுக்கப்பட்டது",
  "sh.ly.link": "கார்டு லிங்க்",
  "sh.ly.delq": "இந்த கார்டையும் அதன் ஸ்டாம்ப்களையும் நீக்கவா?",
  "sh.ly.note": "வாடிக்கையாளர் தன்னிடமுள்ள கார்டை மாற்றக்கூடும்; இங்குள்ள உங்கள் ஸ்டாம்ப்களே இறுதியானவை. லிங்கை உருவாக்கிய நாளின் ஸ்டாம்ப்களை கார்டு காட்டும்.",
  "sh.sf.t": "ஸ்டாஃப் போன் வியூ",
