  "sh.sf.i.adv": "அட்வான்ஸ்களும் பேலன்ஸும்",
  "sh.sf.warn": "சம்பளம் தனிப்பட்டது.",
  "sh.sf.warn2": "பாஸ்கோடு கட்டாயம். அதை ஊழியரிடம் நேரில் அல்லது போன் காலில் கொடுங்கள், லிங்க் உள்ள அதே சாட்டில் அல்ல.",
  "sh.sf.none": "இன்னும் சம்பளச் சீட்டு சேவ் ஆகவில்லை.",
