  "sh.or.t": "கேட்டலாக்கிலிருந்து வந்த ஆர்டர்கள்",
  "sh.or.h": "வாடிக்கையாளர் அனுப்பிய WhatsApp ஆர்டரை பேஸ்ட் செய்யுங்கள். அது வரி வரியாகப் படிக்கப்பட்டு, சேல்ஸ் ஆர்டர் மேக்கரில் நீங்கள் முடிக்கும் டிராஃப்ட் சேல்ஸ் ஆர்டராக மாற்றப்படும்.",
