  "sh.or.note": "வாடிக்கையாளர் பார்த்த விலைகளையே டிராஃப்ட் பயன்படுத்துகிறது. உறுதி செய்யும் முன் ஸ்டாக், விலை, வாடிக்கையாளர் விவரங்களைச் சரிபாருங்கள்.",
