  "cx.help.emi": "குறையும் பேலன்ஸில் கடனின் மாதத் தவணை, முழு மாதவாரி அட்டவணையுடன்.",
  "cx.help.sip": "நீங்கள் எதிர்பார்க்கும் ரிட்டர்னில் மாத முதலீடு எவ்வளவு வளரக்கூடும். ரிட்டர்ன் ஒரு ஊகம், உறுதி அல்ல.",
  "cx.help.hra": "வீட்டு வாடகைப் படியின் (HRA) வரியில்லாத பகுதி (பழைய வரி முறை): மூன்று தொகைகளில் குறைந்தது.",
  "cx.help.stamp": "சொத்து விலையுடன் சேர்க்கப்படும் ஸ்டாம்ப் டியூட்டி, பதிவுக் கட்டணம், மற்ற கட்டணங்கள். உங்கள் மாநிலம் வசூலிக்கும் ரேட்டுகளை டைப் செய்யுங்கள்.",
  "cx.help.margin": "லாபம், விற்பனை விலையில் மார்ஜின், அடக்க விலையில் மார்க்அப். அடக்க விலையும் விற்பனை விலையும், அல்லது அடக்க விலையும் ஒரு சதவீதமும் டைப் செய்யுங்கள்.",
