  "pk.title": "தொழில் பேக்குகள்",
  "pk.limit": "பேக் சேர்க்க மட்டுமே செய்யும். நீங்கள் ஏற்கெனவே சேவ் செய்ததை நீக்கவோ மாற்றவோ செய்யாது: அதே பெயருள்ள ஐட்டம் விடப்படும், நீங்கள் ஏற்கெனவே நிரப்பிய செட்டிங் வைக்கப்படும், எதுவும் ஆஃப் செய்யப்படாது. விற்பனை விலைகள் நீங்கள் டைப் செய்யக் காலியாக விடப்படும். ஐட்டம் பெயர்களும் குறிப்புகளும் ஆங்கிலத்தில் இருக்கும்.",
