  "cap.intro": "உங்கள் சப்ளையரின் பில்லின் போட்டோவை எடுங்கள் அல்லது தேர்ந்தெடுங்கள். டெக்ஸ்ட் இந்த டிவைஸிலேயே படிக்கப்படும், போட்டோ எங்கும் அனுப்பப்படாது. எதுவும் சேவ் ஆகும் முன் ஒவ்வொரு ஃபீல்டையும் நீங்கள் சரிபார்ப்பீர்கள்.",
  "cap.first": "முதல் முறை, படிக்கும் புரோகிராம் ஒருமுறை டவுன்லோட் ஆகும் (ஆங்கிலத்துக்கு சுமார் 7 MB, ஹிந்திக்கு 6 MB), பிறகு இந்த டிவைஸிலேயே வைக்கப்படும்.",
