  "cp.rows_nosup": "Set a supplier's size below and its bills will show here.",
  "cp.accept": "Days are counted from the bill date, because the App does not know the day the goods were accepted. If you accepted them later, your real limit is later too.",
  "cp.rate_t": "Interest estimate (optional)",
  "cp.rate_l": "RBI Bank Rate (% a year)",
  "cp.rate_p": "Under section 16 of the MSMED Act a supplier can claim interest on a late payment at 3 times the RBI Bank Rate, compounded every month. Type the current Bank Rate (see the RBI website) to see an estimate. It is only an estimate: the supplier's claim and the exact day counting can differ.",
  "cp.int_note": "Estimated interest the suppliers could claim on these bills:",
  "cp.ye_t": "Year-end report: unpaid bills past the limit",
  "cp.ye_p": "On 31 March, bills to micro and small suppliers that are still unpaid and past the limit may lose their deduction for that year. Pay them before 31 March, or take this list to your CA.",
  "cp.ye_fy": "Financial year",
  "cp.ye_h": "{b}: unpaid MSME bills past the limit on {d}",
  "cp.ye_cur": "This year has not ended yet: the list shows the bills that will be past the limit on 31 March if they are still unpaid then.",
  "cp.ye_sum": "Bills: {n}. Unpaid beyond the limit: {a}. The deduction on this amount is at risk for the year.",
  "cp.ye_note": "Amounts are the full unpaid bill value, tax included, as saved in the App. Your CA decides what is finally disallowed.",
  "cp.ye_none": "No unpaid bill to a micro or small supplier is past its limit on that date.",
  "cp.ye_unk": "Suppliers with open bills but no size set are not in this list: {n}.",
  "cp.law": "Rule used: a sum owed to a micro or small enterprise beyond the time limit of section 15 of the MSMED Act is allowed only in the year it is actually paid (section 43B(h), Income-tax Act 1961; section 37(2)(g), Income-tax Act 2025). Read on the Income Tax Department website on 17 November 2026. This is not legal or tax advice: ask your CA.",
  "cp.xl": "Excel",
  "cp.print": "Print",
