  "cp.h_see": "See MSME payables",
  "cp.sup_t": "Suppliers: size, Udyam number, agreed days",
  "cp.sup_p": "Set the size from the supplier's Udyam certificate. Only micro and small suppliers are checked. Changes are saved at once.",
  "cp.f_size": "Size",
  "cp.f_ud": "Udyam no.",
  "cp.f_ag": "Days agreed in writing",
  "cp.f_ag_h": "Days agreed in writing with the supplier, 1 to 45. Leave it 0 or empty if nothing is written: then 15 days apply. More than 45 is counted as 45.",
  "cp.h_size": "From the supplier's Udyam certificate. Only micro and small suppliers are checked for the payment limit.",
