  "cp.special": "Your business state is one of the hill states with the lower composition limit of ₹75 lakh for goods: Arunachal Pradesh, Manipur, Meghalaya, Mizoram, Nagaland, Sikkim, Tripura, Uttarakhand.",
  "cp.rc_t": "From 1 January 2027: e-invoice for more supplies",
  "cp.rc_p": "Notification 04/2026-Central Tax (26 October 2026) extends e-invoicing from 1 January 2027 to supplies on which the buyer pays tax under reverse charge (for example a purchase from an unregistered supplier) and to import of services, for businesses above ₹5 crore. Read from the notification text on 17 November 2026; check the notification before you rely on it.",
  "cp.lim_disc": "These are reminders worked out from your own records, not advice. Turnover under the law includes more than the sales saved here. Ask your CA.",
  "cp.si2027": "From 1 January 2027 a self invoice for a reverse charge purchase from an unregistered supplier may also need an e-invoice (IRN) if your turnover is above ₹5 crore (Notification 04/2026-Central Tax). Check the notification. This App cannot make the e-invoice file for a self invoice yet.",
