NS.addLang("ta",{"g1.w.r12": "{no}: a line of goods has GST at 12%. From 22 September 2025 goods are at 5% or 18% (12% stays only for a few services). Check the rate.", "g1.w.nbefore": "Note {no} is dated before its invoice {o}. A credit or debit note cannot come before the bill it changes.", "c.r12": "A line of goods has GST at 12%. From 22 September 2025 most goods moved to 5% or 18% (12% stays only for a few services). Save with 12% anyway?", "c.nbefore": "This note is dated before its invoice. A credit or debit note cannot come before the bill it changes. Save anyway?", "w5.tds194c": "For contractors (393(1) Sl. 6(i), old 194C) TDS is 1% for an individual or HUF and 2% for others. This PAN (4th letter {c}) means {r}%."});
